script:
(function () {
  'use strict';
  // Pension payment options valued at the age the pension starts (month 0). Payments are made at
  // the start of each month and rise by the COLA once a year. Weight of month k:
  //   w(k) = (1 + cola)^floor(k/12) / (1 + i)^k, i = (1 + discount rate)^(1/12) - 1
  // With Y = your months of life and S = your spouse's months (both from the start date):
  //   single life      = A x sum(w, 0..Y)
  //   joint, share s   = A x sum(w, 0..Y) + s x A x sum(w, Y..S)    (survivor only if S > Y)
  //   guaranteed G mo. = A x sum(w, 0..Y) + A x sum(w, Y..G)        (beneficiary if Y < G)
  // Values use prefix sums of w. "Single life wins if you live past": the first death age at
  // which single life's value reaches the option's value, scanning month by month to age 120.
  // CHECKS (Node, scratch tests): 0% discount, 0% COLA, single $2,500 for 20 years = $600,000;
  // joint 50% $2,300 for 20 years + $1,150 for 7 more years = $552,000 + $96,600 = $648,600;
  // $2,500 a month for 20 years at 4% = closed-form annuity-due 2,500 x (1 - v^240) / (1 - v),
  // v = 1.04^(-1/12) -> $416,490.57; guaranteed 10 years with death at month 0 = $2,400 x 120 at
  // 0%; single vs joint 100% at 0%: 2,500 x m = 2,100 x m + 2,100 x (324 - m) -> m = 272.16 months.
  function weights(n, i, cola) {
    var P = [0];
    for (var k = 0; k < n; k++) P.push(P[k] + Math.pow(1 + cola, Math.floor(k / 12)) / Math.pow(1 + i, k));
    return P;
  }

  // Value of option o (amount A, survivor share s or guaranteed months g) when you live Y months.
  function value(o, Y, S, P) {
    var own = o.A * P[Y];
    if (o.g) return own + (o.g > Y ? o.A * (P[o.g] - P[Y]) : 0);
    return own + (S > Y ? o.s * o.A * (P[S] - P[Y]) : 0);
  }

  // First month of your death at which single life is worth at least option o; null if never.
  function breakEven(single, o, maxY, S, P) {
    for (var m = 0; m <= maxY; m++) if (value(single, m, S, P) >= value(o, m, S, P) - 1e-9) return m;
    return null;
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 || !isFinite(x) ? 0 : x); } };

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function fmtAge(a) { var y = Math.floor(a + 1e-9), m = Math.round((a - y) * 12); if (m === 12) { y += 1; m = 0; } return y + (m ? ' and ' + m + ' month' + (m > 1 ? 's' : '') : ''); }
  function fillRows(id, rows) {
    var body = document.getElementById(id);
    body.textContent = '';
    rows.forEach(function (row) {
      var tr = document.createElement('tr');
      row.forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  function update() {
    var age = Math.round(num('poAge')), life = Math.round(num('poLife')), spAge = Math.round(num('poSpAge')),
        spLife = Math.round(num('poSpLife')), early = Math.round(num('poEarly')), rate = num('poRate'), cola = num('poCola'),
        pcYears = Math.round(num('poPcYears'));
    var amts = { single: num('poSingle'), j50: num('poJ50'), j75: num('poJ75'), j100: num('poJ100'), pc: num('poPc') };
    var error = document.getElementById('poError');
    var bad = [age, life, spAge, spLife, early, rate, cola, pcYears, amts.single, amts.j50, amts.j75, amts.j100, amts.pc].some(isNaN) ||
              age < 40 || age > 90 || life <= age || life > 120 || spAge < 18 || spAge > 100 || spLife <= spAge ||
              spLife > 120 || early < age || early > 120 || rate < 0 || rate > 15 || cola < 0 || cola > 10 ||
              pcYears < 1 || pcYears > 30 || amts.single < 0 || amts.j50 < 0 || amts.j75 < 0 || amts.j100 < 0 || amts.pc < 0;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Check the ages: the pension starts from 40 to 90, each life expectancy must be above the current age (up to 120) ' +
                          'and the early-death age from the start age to 120. Use non-negative amounts, a rate up to 15%, an increase up to 10% ' +
                          'and a guaranteed period of 1 to 30 years.';
      return;
    }
    var opts = [
      { key: 'single', name: 'Single life', short: 'Single life', A: amts.single, s: 0 },
      { key: 'j50', name: 'Joint and 50% survivor', short: 'Joint 50%', A: amts.j50, s: 0.5 },
      { key: 'j75', name: 'Joint and 75% survivor', short: 'Joint 75%', A: amts.j75, s: 0.75 },
      { key: 'j100', name: 'Joint and 100% survivor', short: 'Joint 100%', A: amts.j100, s: 1 },
      { key: 'pc', name: 'Life with ' + pcYears + ' years guaranteed', short: pcYears + ' years guaranteed', A: amts.pc, s: 0, g: pcYears * 12 }
    ];
    var Y = (life - age) * 12, E = (early - age) * 12, S = (spLife - spAge) * 12, maxY = (120 - age) * 12;
    var P = weights(Math.max(maxY, S, pcYears * 12), Math.pow(1 + rate / 100, 1 / 12) - 1, cola / 100);
    var offered = opts.filter(function (o) { return o.A > 0; });
    set('poEarlyHead', 'Value, death at ' + early);
    set('poRiskPcHead', pcYears + ' years guaranteed');
    set('poBestEarlyLabel', 'Highest value if you die at ' + early);
    set('poOutlive', Math.max(0, S - Y) / 12 + ' years');

    if (!offered.length) {
      ['poBestExpected', 'poBestEarly', 'poSurvCost'].forEach(function (id) { set(id, '–'); });
      set('poSummary', 'Enter the monthly amount for at least one option.');
      fillRows('poOptions', []); fillRows('poRisk', []);
      return;
    }
    offered.forEach(function (o) { o.vExp = value(o, Y, S, P); o.vEarly = value(o, E, S, P); });
    var bestExp = offered.reduce(function (a, b) { return b.vExp > a.vExp + 0.005 ? b : a; });
    var bestEarly = offered.reduce(function (a, b) { return b.vEarly > a.vEarly + 0.005 ? b : a; });
    set('poBestExpected', bestExp.name);
    set('poBestEarly', bestEarly.name);
    set('poSurvCost', amts.single > 0 && amts.j100 > 0 ? money.format(amts.single - amts.j100) : '–');

    var single = opts[0], text = 'If you both reach your life expectancies, ' + bestExp.name.toLowerCase() + ' is worth the most, ' +
      money.format(bestExp.vExp) + '. If you die at ' + early + ', ' + bestEarly.name.toLowerCase() + ' is worth the most, ' +
      money.format(bestEarly.vEarly) + '.';
    if (single.A > 0 && S > E) text += ' On single life your spouse would then receive nothing for about ' + Math.round((S - E) / 12) + ' years.';
    set('poSummary', text);

    fillRows('poOptions', opts.map(function (o) {
      if (!(o.A > 0)) return [o.name, 'Not offered', '–', '–', '–', '–'];
      var after = o.g ? money.format(o.A) + ' until year ' + (o.g / 12) : (o.s > 0 ? money.format(o.A * o.s) + ' to spouse' : money.format(0));
      var be = '–';
      if (o.key !== 'single' && single.A > 0) {
        var m = breakEven(single, o, maxY, S, P);
        be = m === null ? 'Never, to age 120' : (m === 0 ? 'Always' : 'Age ' + fmtAge(age + m / 12));
      }
      return [o.name, money.format(o.A), after, money.format(o.vExp), money.format(o.vEarly), be];
    }));

    var risk = [];
    for (var d = age; d <= 120; d += 5) {
      var Yd = (d - age) * 12;
      risk.push([d].concat(opts.map(function (o) { return o.A > 0 ? money.format(value(o, Yd, S, P)) : 'Not offered'; })));
      if (d >= 100) break;
    }
    fillRows('poRisk', risk);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('poForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
